-- Keep personal media session controls available only to signed-in users.\nrevoke execute on function public.start_circle_panda_media_session(text,uuid) from public, anon;\nrevoke execute on function public.stop_circle_panda_media_session(uuid) from public, anon;\ngrant execute on function public.start_circle_panda_media_session(text,uuid) to authenticated;\ngrant execute on function public.stop_circle_panda_media_session(uuid) to authenticated;\n